// ----------------------------------------------------------------------------
// Формула силы/длительности эффекта (проверена по эталонной таблице примеров):
// значение = base × (1 + навык/200) × (1 + рангиАлхимика×0.20) × (1 + бонусСпециалиста) × (1 + снаряжение/100)
// где бонусСпециалиста = Провизор(+0.25, только положительные эффекты)
//                       + Целитель(+0.25, только "Восстановление здоровья/магии")
//                       ИЛИ Отравитель(+0.25, только отрицательные эффекты)
// ----------------------------------------------------------------------------
function calcAlchemyValue(base, skill, alchemistRank, hasProvisor, hasHealer, hasPoisoner, gearBonusPercent, polarity, effectName) {
    if (base === null) return null; // булевые эффекты (исцеление болезней и т.д.) — без величины
    let specialistBonus = 0;
    if (polarity === 'positive') {
        if (hasProvisor) specialistBonus += 0.25;
        if (hasHealer && (effectName === 'Восстановление здоровья' || effectName === 'Восстановление магии')) specialistBonus += 0.25;
    } else {
        if (hasPoisoner) specialistBonus += 0.25;
    }
    const skillFactor = 1 + (skill || 0) / 200;
    const perkFactor = 1 + (alchemistRank || 0) * 0.20;
    const specialistFactor = 1 + specialistBonus;
    const gearFactor = 1 + (gearBonusPercent || 0) / 100;
    return Math.round(base * skillFactor * perkFactor * specialistFactor * gearFactor);
}

// Цена зелья/яда — адаптация формулы UESP (Gold = Cost × Magnitude^1.1 × Duration^1.1),
// упрощена под наши базовые значения (base-длительность всегда 1 ход).
function calcAlchemyEffectPrice(effectName, magnitude, duration) {
    const info = alchemyBaseEffects[effectName];
    if (!info) return 0;
    const cost = info.priceBase || 5;
    if (info.base === null) return cost; // болезнь/яд-лечение — фиксированная цена
    let price = cost;
    if (magnitude !== null && magnitude !== undefined) {
        const magRatio = Math.max(magnitude / info.base, 0.1);
        price *= Math.pow(magRatio, 1.1);
    }
    if (info.hasDuration && duration) {
        price *= Math.pow(Math.max(duration, 1), 1.1);
    }
    return Math.max(1, Math.round(price));
}

window.alchemyIngredients = alchemyIngredients;
window.alchemyBaseEffects = alchemyBaseEffects;
window.calcAlchemyValue = calcAlchemyValue;
window.calcAlchemyEffectPrice = calcAlchemyEffectPrice;

